+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+}
+
+img { display: block; width: 100%; height: 100%; object-fit: cover; }
+a   { color: inherit; text-decoration: none; }
+ul  { list-style: none; }
+
+.visually-hidden {
+  position: absolute;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+  border: 0;
+}
+
+/* ============================================================
+   LAYOUT UTILITIES
+   ============================================================ */
+.container {
+  max-width: var(--max-w);
+  margin-inline: auto;
+  padding-inline: clamp(1rem, 4vw, 2.5rem);
+}
+
+.section-header {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 1rem;
+  margin-bottom: 2rem;
+}
+
+.section-header h2 {
+  font-family: var(--font-serif);
+  font-size: clamp(1.5rem, 3vw, 2rem);
+  font-weight: 700;
+  letter-spacing: -.02em;
+}
+
+.view-all {
+  font-size: .875rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  white-space: nowrap;
+  display: flex;
+  align-items: center;
+  gap: .25rem;
+  transition: gap var(--transition);
+}
+.view-all:hover { gap: .5rem; }
+.view-all::after { content: '→'; }
+
+/* ============================================================
+   SKIP LINK
+   ============================================================ */
+.skip-link {
+  position: absolute;
+  top: -100%;
+  left: 1rem;
+  background: var(--color-ink);
+  color: #fff;
+  padding: .5rem 1rem;
+  border-radius: var(--radius-sm);
+  font-size: .875rem;
+  font-weight: 600;
+  z-index: 9999;
+  transition: top var(--transition);
+}
+.skip-link:focus { top: 1rem; }
+
+/* ============================================================
+   ANNOUNCEMENT BAR
+   ============================================================ */
+.announcement-bar {
+  background: var(--color-ink);
+  color: #fff;
+  text-align: center;
+  padding: .6rem 1rem;
+  font-size: .8125rem;
+  font-weight: 500;
+  letter-spacing: .02em;
+}
+.announcement-bar a { text-decoration: underline; color: inherit; }
+
+/* ============================================================
+   HEADER / NAV
+   ============================================================ */
+.site-header {
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+  position: sticky;
+  top: 0;
+  z-index: 100;
+}
+
+.header-inner {
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  align-items: center;
+  gap: 1rem;
+  padding-block: 1rem;
+}
+
+.site-logo {
+  font-family: var(--font-serif);
+  font-size: 1.5rem;
+  font-weight: 700;
+  letter-spacing: -.03em;
+  grid-column: 2;
+  justify-self: center;
+}
+.site-logo span { color: var(--color-accent); }
+
+.primary-nav { grid-column: 1; }
+.primary-nav ul { display: flex; gap: 1.75rem; }
+.primary-nav a {
+  font-size: .9rem;
+  font-weight: 500;
+  color: var(--color-ink-muted);
+  transition: color var(--transition);
+}
+.primary-nav a:hover { color: var(--color-ink); }
+
+.header-actions {
+  grid-column: 3;
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  justify-content: flex-end;
+}
+
+.icon-btn {
+  background: none;
+  border: none;
+  cursor: pointer;
+  padding: .5rem;
+  border-radius: var(--radius-sm);
+  color: var(--color-ink);
+  transition: background var(--transition);
+  position: relative;
+  display: flex;
+  align-items: center;
+}
+.icon-btn:hover { background: var(--color-bg); }
+.icon-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.cart-badge {
+  position: absolute;
+  top: 4px; right: 4px;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: .625rem;
+  font-weight: 700;
+  width: 16px; height: 16px;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  pointer-events: none;
+}
+
+/* Mobile nav toggle */
+.nav-toggle {
+  display: none;
+  background: none;
+  border: none;
+  cursor: pointer;
+  padding: .5rem;
+  color: var(--color-ink);
+  border-radius: var(--radius-sm);
+}
+.nav-toggle:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+/* ============================================================
+   HERO
+   ============================================================ */
+.hero {
+  background: var(--color-ink);
+  color: #fff;
+  overflow: hidden;
+  position: relative;
+  min-height: min(80vh, 640px);
+  display: grid;
+}
+
+.hero-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  align-items: center;
+  gap: 2rem;
+  min-height: inherit;
+}
+
+.hero-content {
+  padding-block: 4rem;
+  position: relative;
+  z-index: 2;
+}
+
+.hero-eyebrow {
+  display: inline-block;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  padding: .35rem .75rem;
+  border-radius: var(--radius-sm);
+  margin-bottom: 1.25rem;
+}
+
+.hero-title {
+  font-family: var(--font-serif);
+  font-size: clamp(2.5rem, 6vw, 4.25rem);
+  line-height: 1.08;
+  letter-spacing: -.03em;
+  margin-bottom: 1.25rem;
+}
+
+.hero-title em { font-style: italic; color: #e8c9a0; }
+
+.hero-desc {
+  font-size: 1.0625rem;
+  color: rgba(255,255,255,.72);
+  max-width: 42ch;
+  margin-bottom: 2rem;
+  line-height: 1.65;
+}
+
+.hero-cta-group {
+  display: flex;
+  flex-wrap: wrap;
+  gap: .75rem;
+  align-items: center;
+}
+
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: .5rem;
+  padding: .8rem 1.75rem;
+  border-radius: var(--radius-sm);
+  font-size: .9375rem;
+  font-weight: 600;
+  cursor: pointer;
+  border: 2px solid transparent;
+  transition: background var(--transition), color var(--transition), border-color var(--transition), transform var(--transition);
+}
+.btn:focus-visible {
+  outline: 3px solid var(--color-accent);
+  outline-offset: 3px;
+}
+.btn:active { transform: scale(.98); }
+
+.btn-primary {
+  background: var(--color-accent);
+  color: #fff;
+  border-color: var(--color-accent);
+}
+.btn-primary:hover { background: #b0402a; border-color: #b0402a; }
+
+.btn-ghost {
+  background: transparent;
+  color: #fff;
+  border-color: rgba(255,255,255,.4);
+}
+.btn-ghost:hover { border-color: #fff; background: rgba(255,255,255,.08); }
+
+.btn-outline {
+  background: transparent;
+  color: var(--color-accent);
+  border-color: var(--color-accent);
+}
+.btn-outline:hover { background: var(--color-accent); color: #fff; }
+
+.hero-image-wrap {
+  height: 100%;
+  min-height: 480px;
+  position: relative;
+  overflow: hidden;
+}
+
+.hero-image-wrap::before {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(135deg, rgba(30,20,10,.45) 0%, transparent 60%);
+  z-index: 1;
+}
+
+.hero-image-wrap img {
+  height: 100%;
+  object-position: center;
+  transition: transform 6s ease;
+}
+
+.hero-image-wrap:hover img { transform: scale(1.03); }
+
+.hero-stats {
+  display: flex;
+  gap: 2.5rem;
+  margin-top: 2.5rem;
+  padding-top: 2rem;
+  border-top: 1px solid rgba(255,255,255,.15);
+}
+
+.hero-stat-value {
+  font-family: var(--font-serif);
+  font-size: 1.875rem;
+  font-weight: 700;
+  line-height: 1;
+}
+
+.hero-stat-label {
+  font-size: .8rem;
+  color: rgba(255,255,255,.55);
+  margin-top: .25rem;
+  letter-spacing: .04em;
+}
+
+/* ============================================================
+   CATEGORY STRIP
+   ============================================================ */
+.categories {
+  padding-block: 3rem;
+}
+
+.categories-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
+  gap: 1rem;
+}
+
+.category-card {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .75rem;
+  padding: 1.5rem 1rem;
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-md);
+  cursor: pointer;
+  transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
+  text-align: center;
+}
+
+.category-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-3px);
+  border-color: var(--color-accent);
+}
+
+.category-card:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.category-icon {
+  width: 52px; height: 52px;
+  background: var(--color-bg);
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 1.5rem;
+  transition: background var(--transition);
+}
+.category-card:hover .category-icon { background: var(--color-accent-lt); }
+
+.category-name {
+  font-size: .875rem;
+  font-weight: 600;
+  line-height: 1.3;
+}
+
+.category-count {
+  font-size: .75rem;
+  color: var(--color-ink-muted);
+}
+
+/* ============================================================
+   FEATURED PRODUCTS
+   ============================================================ */
+.featured-products { padding-block: 3rem; }
+
+.products-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
+  gap: 1.5rem;
+}
+
+.product-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  transition: box-shadow var(--transition), transform var(--transition);
+  display: flex;
+  flex-direction: column;
+}
+
+.product-card:hover {
+  box-shadow: var(--shadow-lg);
+  transform: translateY(-4px);
+}
+
+.product-image-wrap {
+  position: relative;
+  aspect-ratio: 4/3;
+  overflow: hidden;
+  background: var(--color-bg);
+}
+
+.product-image-wrap img {
+  transition: transform .4s ease;
+}
+.product-card:hover .product-image-wrap img { transform: scale(1.06); }
+
+.product-badge {
+  position: absolute;
+  top: .75rem; left: .75rem;
+  padding: .25rem .6rem;
+  border-radius: var(--radius-sm);
+  font-size: .7rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  z-index: 2;
+}
+.badge-new     { background: var(--color-deal); color: #fff; }
+.badge-sale    { background: var(--color-accent); color: #fff; }
+.badge-limited { background: #f0a500; color: #fff; }
+
+.product-actions {
+  position: absolute;
+  bottom: .75rem;
+  right: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .4rem;
+  opacity: 0;
+  transform: translateX(8px);
+  transition: opacity var(--transition), transform var(--transition);
+  z-index: 2;
+}
+.product-card:hover .product-actions,
+.product-card:focus-within .product-actions {
+  opacity: 1;
+  transform: translateX(0);
+}
+
+.action-btn {
+  width: 36px; height: 36px;
+  background: #fff;
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  cursor: pointer;
+  font-size: 1rem;
+  transition: background var(--transition), border-color var(--transition);
+  box-shadow: var(--shadow-sm);
+}
+.action-btn:hover { background: var(--color-accent); border-color: var(--color-accent); filter: brightness(10); }
+.action-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.product-body {
+  padding: 1.25rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+}
+
+.product-category {
+  font-size: .7rem;
+  font-weight: 600;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--color-ink-muted);
+  margin-bottom: .4rem;
+}
+
+.product-name {
+  font-weight: 600;
+  font-size: .9375rem;
+  margin-bottom: .5rem;
+  line-height: 1.4;
+}
+
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .4rem;
+  margin-bottom: .75rem;
+}
+
+.stars { color: #f0a500; font-size: .875rem; }
+
+.rating-count {
+  font-size: .75rem;
+  color: var(--color-ink-muted);
+}
+
+.product-footer {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: .5rem;
+  margin-top: auto;
+  padding-top: .75rem;
+  border-top: 1px solid var(--color-border);
+}
+
+.price-group {
+  display: flex;
+  align-items: baseline;
+  gap: .4rem;
+}
+
+.price-current {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: var(--color-ink);
+}
+
+.price-original {
+  font-size: .875rem;
+  color: var(--color-ink-muted);
+  text-decoration: line-through;
+}
+
+.price-discount {
+  font-size: .75rem;
+  font-weight: 700;
+  color: var(--color-accent);
+}
+
+.add-to-cart-btn {
+  background: var(--color-ink);
+  color: #fff;
+  border: none;
+  border-radius: var(--radius-sm);
+  padding: .5rem .85rem;
+  font-size: .8125rem;
+  font-weight: 600;
+  cursor: pointer;
+  white-space: nowrap;
+  transition: background var(--transition), transform var(--transition);
+}
+.add-to-cart-btn:hover { background: var(--color-accent); }
+.add-to-cart-btn:active { transform: scale(.96); }
+.add-to-cart-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+.add-to-cart-btn.added {
+  background: #2a7a4b;
+}
+
+/* ============================================================
+   DEALS BANNER
+   ============================================================ */
+.deals-section { padding-block: 3rem; }
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1.6fr 1fr;
+  gap: 1.25rem;
+}
+
+.deal-card {
+  position: relative;
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  min-height: 360px;
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  padding: 2.5rem;
+  color: #fff;
+}
+
+.deal-card-bg {
+  position: absolute;
+  inset: 0;
+  z-index: 0;
+  transition: transform .5s ease;
+}
+.deal-card:hover .deal-card-bg { transform: scale(1.04); }
+
+.deal-card::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,.7) 0%, rgba(0,0,0,.1) 60%, transparent 100%);
+  z-index: 1;
+}
+
+.deal-content { position: relative; z-index: 2; }
+
+.deal-eyebrow {
+  display: inline-block;
+  background: var(--color-accent);
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  padding: .3rem .65rem;
+  border-radius: var(--radius-sm);
+  margin-bottom: .85rem;
+}
+
+.deal-title {
+  font-family: var(--font-serif);
+  font-size: clamp(1.4rem, 3vw, 2rem);
+  line-height: 1.15;
+  margin-bottom: .6rem;
+}
+
+.deal-desc {
+  font-size: .875rem;
+  color: rgba(255,255,255,.8);
+  margin-bottom: 1.25rem;
+  line-height: 1.6;
+  max-width: 38ch;
+}
+
+.deal-timer {
+  display: flex;
+  gap: .75rem;
+  margin-bottom: 1.5rem;
+}
+
+.timer-unit {
+  text-align: center;
+  background: rgba(255,255,255,.15);
+  backdrop-filter: blur(6px);
+  border-radius: var(--radius-sm);
+  padding: .5rem .65rem;
+  min-width: 52px;
+}
+
+.timer-value {
+  display: block;
+  font-size: 1.25rem;
+  font-weight: 700;
+  line-height: 1;
+  font-variant-numeric: tabular-nums;
+}
+
+.timer-label {
+  display: block;
+  font-size: .6rem;
+  text-transform: uppercase;
+  letter-spacing: .07em;
+  color: rgba(255,255,255,.7);
+  margin-top: .2rem;
+}
+
+/* Secondary deals column */
+.deal-stack {
+  display: flex;
+  flex-direction: column;
+  gap: 1.25rem;
+}
+
+.deal-card-sm {
+  flex: 1;
+  min-height: 0;
+}
+
+/* ============================================================
+   EDITORIAL / CONTENT
+   ============================================================ */
+.editorial { padding-block: 3rem; }
+
+.editorial-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 1.5rem;
+}
+
+.editorial-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+
+.editorial-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-3px);
+}
+
+.editorial-image-wrap {
+  aspect-ratio: 16/9;
+  overflow: hidden;
+}
+
+.editorial-image-wrap img {
+  transition: transform .45s ease;
+}
+.editorial-card:hover .editorial-image-wrap img { transform: scale(1.06); }
+
+.editorial-body {
+  padding: 1.5rem;
+}
+
+.editorial-tag {
+  display: inline-block;
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .6rem;
+}
+
+.editorial-title {
+  font-family: var(--font-serif);
+  font-size: 1.125rem;
+  font-weight: 700;
+  line-height: 1.35;
+  margin-bottom: .6rem;
+}
+
+.editorial-excerpt {
+  font-size: .875rem;
+  color: var(--color-ink-muted);
+  line-height: 1.65;
+  margin-bottom: 1.25rem;
+}
+
+.editorial-meta {
+  display: flex;
+  align-items: center;
+  gap: .75rem;
+  font-size: .78rem;
+  color: var(--color-ink-muted);
+}
+
+.editorial-avatar {
+  width: 28px; height: 28px;
+  border-radius: 50%;
+  overflow: hidden;
+  flex-shrink: 0;
+  background: var(--color-bg);
+}
+
+.read-more {
+  display: inline-flex;
+  align-items: center;
+  gap: .25rem;
+  font-size: .8125rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  transition: gap var(--transition);
+}
+.read-more:hover { gap: .5rem; }
+.read-more::after { content: '→'; }
+
+/* ============================================================
+   BRAND TRUST STRIP
+   ============================================================ */
+.trust-strip {
+  background: var(--color-surface);
+  border-block: 1px solid var(--color-border);
+  padding-block: 2.25rem;
+}
+
+.trust-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 1.5rem;
+}
+
+.trust-item {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  text-align: center;
+  gap: .6rem;
+}
+
+.trust-icon {
+  font-size: 1.75rem;
+  color: var(--color-accent);
+}
+
+.trust-label {
+  font-weight: 700;
+  font-size: .9rem;
+}
+
+.trust-sublabel {
+  font-size: .78rem;
+  color: var(--color-ink-muted);
+  line-height: 1.4;
+}
+
+/* ============================================================
+   NEWSLETTER
+   ============================================================ */
+.newsletter {
+  background: var(--color-deal);
+  color: #fff;
+  padding-block: 4rem;
+  text-align: center;
+}
+
+.newsletter-inner { max-width: 540px; margin-inline: auto; }
+
+.newsletter h2 {
+  font-family: var(--font-serif);
+  font-size: clamp(1.75rem, 4vw, 2.5rem);
+  margin-bottom: .75rem;
+  letter-spacing: -.02em;
+}
+
+.newsletter p {
+  color: rgba(255,255,255,.72);
+  margin-bottom: 2rem;
+  font-size: 1.0625rem;
+}
+
+.newsletter-form {
+  display: flex;
+  gap: .6rem;
+  max-width: 440px;
+  margin-inline: auto;
+}
+
+.newsletter-form input[type="email"] {
+  flex: 1;
+  padding: .8rem 1.1rem;
+  border: 2px solid rgba(255,255,255,.25);
+  border-radius: var(--radius-sm);
+  background: rgba(255,255,255,.1);
+  color: #fff;
+  font-size: .9375rem;
+  font-family: inherit;
