+  badge.hidden = count === 0;
+  document.getElementById('cart-btn')
+    .setAttribute('aria-label', `Shopping cart, ${count} item${count !== 1 ? 's' : ''}`);
+}
+
+// ── Cart drawer ──────────────────────────────────────────────
+function openCart() {
+  const overlay = document.getElementById('cart-overlay');
+  const drawer  = document.getElementById('cart-drawer');
+  overlay.classList.add('open');
+  drawer.classList.add('open');
+  drawer.setAttribute('aria-hidden', 'false');
+  document.body.style.overflow = 'hidden';
+  document.getElementById('cart-close-btn').focus();
+}
+
+function closeCart() {
+  const overlay = document.getElementById('cart-overlay');
+  const drawer  = document.getElementById('cart-drawer');
+  overlay.classList.remove('open');
+  drawer.classList.remove('open');
+  drawer.setAttribute('aria-hidden', 'true');
+  document.body.style.overflow = '';
+  document.getElementById('cart-btn').focus();
+}
+
+// ── Search modal ─────────────────────────────────────────────
+function openSearch() {
+  const overlay = document.getElementById('search-overlay');
+  overlay.classList.add('open');
+  overlay.setAttribute('aria-hidden', 'false');
+  document.body.style.overflow = 'hidden';
+  setTimeout(() => document.getElementById('search-input').focus(), 50);
+}
+
+function closeSearch() {
+  const overlay = document.getElementById('search-overlay');
+  overlay.classList.remove('open');
+  overlay.setAttribute('aria-hidden', 'true');
+  document.body.style.overflow = '';
+  document.getElementById('search-btn').focus();
+}
+
+// ── Toast notifications ──────────────────────────────────────
+function showToast(message) {
+  const container = document.getElementById('toast-container');
+  const toast = document.createElement('div');
+  toast.className = 'toast';
+  toast.setAttribute('role', 'status');
+  toast.setAttribute('aria-live', 'polite');
+  toast.textContent = message;
+  container.appendChild(toast);
+  setTimeout(() => {
+    toast.classList.add('removing');
+    toast.addEventListener('animationend', () => toast.remove());
+  }, 3000);
+}
+
+// ── Add to cart handler ──────────────────────────────────────
+function handleAddToCart(btn) {
+  const card = btn.closest('[data-product-id]');
+  if (!card) return;
+
+  const product = {
+    id:      card.dataset.productId,
+    name:    card.dataset.productName,
+    price:   parseFloat(card.dataset.productPrice),
+    img:     card.dataset.productImg,
+    variant: card.dataset.productVariant || '',
+  };
+
+  cart.add(product);
+  showToast(`"${product.name}" added to cart`);
+
+  btn.textContent = '✓ Added';
+  btn.classList.add('added');
+  btn.setAttribute('aria-label', `${product.name} added to cart`);
+  setTimeout(() => {
+    btn.textContent = 'Add to Cart';
+    btn.classList.remove('added');
+    btn.setAttribute('aria-label', `Add ${product.name} to cart`);
+  }, 1800);
+}
+
+// ── Countdown timer ──────────────────────────────────────────
+function startCountdown(endTime) {
+  function tick() {
+    const now  = Date.now();
+    const diff = Math.max(0, endTime - now);
+    const h  = Math.floor(diff / 3_600_000);
+    const m  = Math.floor((diff % 3_600_000) / 60_000);
+    const s  = Math.floor((diff % 60_000) / 1000);
+
+    const pad = n => String(n).padStart(2, '0');
+    const hEl = document.getElementById('timer-hours');
+    const mEl = document.getElementById('timer-mins');
+    const sEl = document.getElementById('timer-secs');
+    if (hEl) hEl.textContent = pad(h);
+    if (mEl) mEl.textContent = pad(m);
+    if (sEl) sEl.textContent = pad(s);
+
+    if (diff > 0) requestAnimationFrame(tick);
+  }
+  tick();
+}
+
+// ── Mobile nav toggle ─────────────────────────────────────────
+function initMobileNav() {
+  const toggle = document.getElementById('nav-toggle');
+  const nav    = document.getElementById('primary-nav');
+  if (!toggle || !nav) return;
+
+  toggle.addEventListener('click', () => {
+    const isOpen = nav.classList.toggle('open');
+    toggle.setAttribute('aria-expanded', isOpen);
+    toggle.setAttribute('aria-label', isOpen ? 'Close menu' : 'Open menu');
+  });
+}
+
+// ── Keyboard trapping for drawers ─────────────────────────────
+function trapFocus(element) {
+  const focusable = element.querySelectorAll(
+    'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
+  );
+  const first = focusable[0];
+  const last  = focusable[focusable.length - 1];
+
+  element.addEventListener('keydown', e => {
+    if (e.key !== 'Tab') return;
+    if (e.shiftKey) {
+      if (document.activeElement === first) { e.preventDefault(); last.focus(); }
+    } else {
+      if (document.activeElement === last) { e.preventDefault(); first.focus(); }
+    }
+  });
+}
+
+// ── Newsletter form ───────────────────────────────────────────
+function initNewsletter() {
+  const form = document.getElementById('newsletter-form');
+  if (!form) return;
+
+  form.addEventListener('submit', e => {
+    e.preventDefault();
+    const input = form.querySelector('input[type="email"]');
+    if (!input.value) return;
+    showToast('You\'re subscribed! Welcome to the family 🎉');
+    input.value = '';
+  });
+}
+
+// ── Intersection observer for fade-in ─────────────────────────
+function initReveal() {
+  if (!('IntersectionObserver' in window)) return;
+
+  const style = document.createElement('style');
+  style.textContent = `
+    .reveal { opacity: 0; transform: translateY(20px); transition: opacity .5s ease, transform .5s ease; }
+    .reveal.visible { opacity: 1; transform: none; }
+  `;
+  document.head.appendChild(style);
+
+  const els = document.querySelectorAll(
+    '.product-card, .editorial-card, .deal-card, .category-card, .trust-item'
+  );
+  els.forEach(el => el.classList.add('reveal'));
+
+  const obs = new IntersectionObserver(entries => {
+    entries.forEach(entry => {
+      if (entry.isIntersecting) {
+        entry.target.classList.add('visible');
+        obs.unobserve(entry.target);
+      }
+    });
+  }, { threshold: 0.12 });
+
+  els.forEach(el => obs.observe(el));
+}
+
+// ── Escape key global handler ─────────────────────────────────
+document.addEventListener('keydown', e => {
+  if (e.key !== 'Escape') return;
+  const cartDrawer = document.getElementById('cart-drawer');
+  if (cartDrawer?.classList.contains('open')) { closeCart(); return; }
+  const searchOverlay = document.getElementById('search-overlay');
+  if (searchOverlay?.classList.contains('open')) { closeSearch(); }
+});
+
+// ── Init ──────────────────────────────────────────────────────
+document.addEventListener('DOMContentLoaded', () => {
+  cart.load();
+  initMobileNav();
+  initNewsletter();
+  initReveal();
+
+  // Focus trap for cart drawer
+  const drawer = document.getElementById('cart-drawer');
+  if (drawer) trapFocus(drawer);
+
+  // Countdown: ends in ~7 hours from page load
+  startCountdown(Date.now() + 7 * 3_600_000 + 23 * 60_000 + 15_000);
+
+  // Close overlays on outside click
+  document.getElementById('cart-overlay')
+    ?.addEventListener('click', e => { if (e.target === e.currentTarget) closeCart(); });
+  document.getElementById('search-overlay')
+    ?.addEventListener('click', e => { if (e.target === e.currentTarget) closeSearch(); });
+});
+
')

